def button(href,label,secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{esc(href)}">{label} <span aria-hidden="true">↗</span></a>'
def cards(lang):
 d=D[lang];out=''
 for slug,p in P.items():
  q=p[lang];out+=f'<article class="project-card {slug}"><a class="project-art" href="{url(lang,"projects/"+slug)}" aria-label="{d["learn"]}: {p["name"]}"><img src="/assets/{p["image"]}" alt="{p["name"]}" width="260" height="260" loading="lazy"></a><div class="project-copy"><p class="kicker">{d["status"]} / {q["state"]}</p><h3><a href="{url(lang,"projects/"+slug)}">{p["name"]} <span aria-hidden="true">↗</span></a></h3><p>{q["summary"]}</p><p class="tags">{p["tags"]}</p></div></article>'
 return '<div class="project-grid">'+out+'</div>'
def service_rows(lang):
 return '<div class="service-list">'+''.join(f'<a class="service-row" href="{url(lang,s[0])}"><span class="number">{s[1]}</span><h3>{s[2]}</h3><p>{s[4]}</p><span aria-hidden="true">↗</span></a>' for s in SERV[lang])+'</div>'
def contact_strip(lang):
 d=D[lang];return f'<section class="contact-strip wrap"><p class="kicker">{d["nav"][4]}</p><h2>{d["contacttitle"]}</h2>{button("mailto:vendas@feverdream.dev",d["email"])}</section>'
def hero(lang,title,intro,kicker='',art=False):
 return f'<section class="hero wrap {"home-hero" if art else "page-hero"}"><div class="hero-copy"><p class="kicker">{kicker or D[lang]["label"]}</p><h1>{title}</h1><p class="lead">{intro}</p>'+ (f'<div class="actions">{button(url(lang,"contact"),D[lang]["talk"])}{button(url(lang,"projects"),D[lang]["explore"],True)}</div>' if art else '')+'</div>'+('<div class="brand-art"><div class="orbital one"></div><div class="orbital two"></div><img src="/assets/feverdream-logo.webp" width="490" height="490" alt="FeverDream — Eye of Horus"><span class="art-caption">PERCEPTION / CURIOSITY / CREATION</span></div>' if art else '')+'</section>'
def content(lang,key):
 d=D[lang]
 if key=='':
  return hero(lang,d['title'],d['intro'],d['eyebrow'],True)+f'<div class="discipline-band"><div class="wrap">AI & AUTOMATION <span>✳</span> SOFTWARE <span>✳</span> LINUX & CLOUD <span>✳</span> INDEPENDENT R&D</div></div><section class="section wrap"><div class="section-heading"><div><p class="kicker">{d["label"]}</p><h2>{d["projecttitle"]}</h2></div><p>{d["projectintro"]}</p></div>'+cards(lang)+f'<a class="text-link" href="{url(lang,"projects")}">{d["allprojects"]} ↗</a></section><section class="section expertise wrap"><div class="section-heading"><div><p class="kicker">{d["nav"][0]}</p><h2>{d["services"]}</h2></div><p>{d["serviceintro"]}</p></div>'+service_rows(lang)+f'</section><section class="story-panel"><div class="wrap story-grid"><p class="kicker">{d["nav"][3]}</p><h2>{d["storytitle"]}</h2><div><p>{d["story"]}</p><a class="text-link" href="{url(lang,"about")}">{d["nav"][3]} ↗</a></div></div></section>'+contact_strip(lang)
 if key=='projects':
  edu=('<h3>Education is part of the picture.</h3><p>Our education work explores AI tutoring, classroom tools, and learning analytics. It sits alongside our systems and infrastructure projects.</p>' if lang=='en' else '<h3>Educação faz parte da nossa história.</h3><p>Nosso trabalho em educação explora tutoria com IA, ferramentas de sala de aula e análise de aprendizagem, ao lado de projetos de sistemas e infraestrutura.</p>')
  return hero(lang,d['projecttitle'],d['projectintro'])+f'<section class="wrap project-section">{cards(lang)}<aside class="education-note"><span class="number">03 / EDUCATION</span><div>{edu}<a class="text-link" href="{url(lang,"contact")}">{d["talk"]} ↗</a></div></aside></section>'+contact_strip(lang)
 if key.startswith('projects/'):
  slug=key.split('/')[-1];p=P[slug];q=p[lang]
  return f'<section class="wrap project-detail"><a class="text-link" href="{url(lang,"projects")}">← {d["back"]}</a><div class="detail-grid"><div><p class="kicker">{d["status"]} / {q["state"]}</p><h1>{p["name"]}</h1><p class="lead">{q["summary"]}</p><p>{q["desc"]}</p><div class="actions">{button(p.get("website",p["repo"]),q["link"])}{button(p["repo"],d["source"],True) if p.get("website") else ""}</div></div><div class="detail-art {slug}"><img src="/assets/{p["image"]}" alt="{p["name"]}" width="350" height="350"></div></div><div class="detail-bottom"><div><p class="kicker">{p["tags"]}</p><ul class="feature-list">'+''.join(f'<li>{x}</li>' for x in q['points'])+f'</ul></div><aside class="status-note"><h2>{"Project status" if lang=="en" else "Estágio do projeto"}</h2><p>{q["note"]}</p></aside></div></section>'+contact_strip(lang)
 if key=='opensource':
  extra=('<h2>Open source means a license.</h2><p>EZpenguin is licensed under GPL-3.0-or-later. Double Agent is source-available for viewing and evaluation; redistribution and commercial hosting require written authorization. Public source does not automatically mean open source.</p>' if lang=='en' else '<h2>Código aberto tem licença.</h2><p>O EZpenguin usa a GPL-3.0-or-later. O Double Agent disponibiliza código para consulta e avaliação; redistribuição e hospedagem comercial exigem autorização por escrito. Código público não significa automaticamente código aberto.</p>')
  return hero(lang,d['opentitle'],d['openintro'])+f'<section class="wrap project-section">{cards(lang)}<div class="reading-panel">{extra}</div></section>'+contact_strip(lang)
 if key=='about':
  return hero(lang,d['storytitle'],d['story'])+f'<section class="wrap about-content"><div class="brand-stamp"><img src="/assets/feverdream-logo.webp" width="300" height="300" alt="FeverDream"></div><div><p class="kicker">FEVERDREAM / SÃO PAULO, BRASIL</p><h2>{"Curiosity is the starting point." if lang=="en" else "A curiosidade é o ponto de partida."}</h2><p class="lead">{d["belief"]}</p><p>{d["projectintro"]}</p>{button(url(lang,"projects"),d["explore"])}</div></section>'+contact_strip(lang)
 if key=='contact':
  faqs= [('What can I contact FeverDream about?','AI and automation, custom software, cloud and self-hosted infrastructure, or a conversation about one of our internal projects.'),('Are the internal projects production-ready?','Each project is at a different stage. EZpenguin is an early release; Double Agent is in architecture and design. Their project pages and repositories explain the current status.'),('How do we start?','Email vendas@feverdream.dev with your goal, current setup, and main constraints. We can discuss an appropriate next step.')] if lang=='en' else [('Sobre o que posso conversar com a FeverDream?','IA e automação, software sob medida, infraestrutura em nuvem ou auto-hospedada, e nossos projetos internos.'),('Os projetos internos estão prontos para produção?','Cada projeto está em um estágio. O EZpenguin tem uma versão inicial; o Double Agent está em arquitetura e design. As páginas dos projetos e os repositórios explicam a situação atual.'),('Como começamos?','Envie um e-mail para vendas@feverdream.dev com seu objetivo, ambiente atual e principais limitações. A partir daí, conversamos sobre o próximo passo.')]
  return hero(lang,d['contacttitle'],d['contactintro'])+f'<section class="wrap contact-content"><div class="email-panel"><p class="kicker">{d["email"]}</p><a class="email-address" href="mailto:vendas@feverdream.dev">vendas@feverdream.dev <span aria-hidden="true">↗</span></a><p>São Paulo, Brasil · English / Português</p><div class="social-links"><a href="https://www.linkedin.com/company/feverdreamdev">LinkedIn ↗</a><a href="https://www.instagram.com/feverdream.dev/">Instagram ↗</a></div></div><h2>{d["faq"]}</h2><div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faqs)+'</div></section>'
 if key in ('ai','dev','cloud','security'):
  s=next(x for x in SERV[lang] if x[0]==key)
  return hero(lang,s[3],s[4],s[2])+f'<section class="wrap service-detail"><div><h2>{s[2]}</h2><ul class="feature-list">'+''.join(f'<li>{x}</li>' for x in s[5])+f'</ul></div><div class="process-list">'+''.join(f'<article><span class="number">0{i+1}</span><div><h3>{t}</h3><p>{d["processdesc"][i]}</p></div></article>' for i,t in enumerate(d['process']))+'</div></section>'+contact_strip(lang)
 raise ValueError(key)
KEYS=['','ai','dev','cloud','security','projects','projects/ezpenguin','projects/double-agent','opensource','about','contact']
TITLES={'en':{'':'AI, Software & Infrastructure','projects':'Internal Projects & R&D','opensource':'Open Source & Source-Available Projects','about':'Our Story & Approach','contact':'Contact — Build with FeverDream'},'pt':{'':'IA, Software e Infraestrutura','projects':'Projetos Internos e Pesquisa','opensource':'Projetos de Código Aberto e Código Disponível','about':'Nossa História e Abordagem','contact':'Contato — Construa com a FeverDream'}}
def metadata(lang,key):
 d=D[lang]
 if key.startswith('projects/'):
  p=P[key.split('/')[-1]];return p['name']+' — '+p[lang]['summary'],p[lang]['desc']
 if key in ('ai','dev','cloud','security'):
  s=next(x for x in SERV[lang] if x[0]==key);return s[2],s[4]
 return TITLES[lang][key], {'':d['intro'],'projects':d['projectintro'],'opensource':d['openintro'],'about':d['belief'],'contact':d['contactintro']}[key]
def page(lang,key):
 d=D[lang];title,desc=metadata(lang,key);title+=' | FeverDream';canonical=BASE+url(lang,key)
 schemas=[{'@type':'Organization','@id':BASE+'/#organization','name':'FeverDream','url':BASE+'/','logo':BASE+'/assets/feverdream-logo.webp','email':'vendas@feverdream.dev','sameAs':['https://www.linkedin.com/company/feverdreamdev','https://www.instagram.com/feverdream.dev/']},{'@type':'WebSite','@id':BASE+'/#website','name':'FeverDream','url':BASE+'/','inLanguage':['en','pt-BR'],'publisher':{'@id':BASE+'/#organization'}},{'@type':'WebPage','@id':canonical+'#webpage','name':title,'description':desc,'url':canonical,'inLanguage':d['lang'],'isPartOf':{'@id':BASE+'/#website'}}]
 if key:
  crumbs=[{'@type':'ListItem','position':1,'name':'FeverDream','item':BASE+url(lang)}]
  if key.startswith('projects/'):crumbs.append({'@type':'ListItem','position':2,'name':d['nav'][1],'item':BASE+url(lang,'projects')})
  crumbs.append({'@type':'ListItem','position':len(crumbs)+1,'name':metadata(lang,key)[0],'item':canonical});schemas.append({'@type':'BreadcrumbList','itemListElement':crumbs})
 navkeys=['ai','projects','opensource','about','contact']
 nav=''.join(f'<a href="{url(lang,k)}"'+(' aria-current="page"' if key==k or (k=='projects' and key.startswith('projects/')) else '')+f'>{n}</a>' for k,n in zip(navkeys,d['nav']))
 head=f'''<!doctype html><html lang="{d['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#f6f2e9"><meta name="keywords" content="FeverDream, AI, software development, Linux, cloud infrastructure, automation, EZpenguin, Double Agent, inteligência artificial, desenvolvimento de software"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{BASE+url('en',key)}"><link rel="alternate" hreflang="pt-BR" href="{BASE+url('pt',key)}"><link rel="alternate" hreflang="x-default" href="{BASE+url('en',key)}"><meta property="og:type" content="website"><meta property="og:site_name" content="FeverDream"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:locale" content="{'en_US' if lang=='en' else 'pt_BR'}"><meta property="og:locale:alternate" content="{'pt_BR' if lang=='en' else 'en_US'}"><meta property="og:image" content="{BASE}/assets/social-preview.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="FeverDream — AI, software and infrastructure"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(desc)}"><meta name="twitter:image" content="{BASE}/assets/social-preview.png"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':schemas},ensure_ascii=False).replace('<','\\u003c')}</script></head>'''
 return head+f'''<body><a class="skip-link" href="#main">{d['skip']}</a><header class="site-header wrap"><a class="brand" href="{url(lang)}" aria-label="FeverDream"><img src="/assets/feverdream-logo.webp" width="48" height="48" alt=""><span>FEVERDREAM<span class="brand-sub">AI / SOFTWARE / INFRASTRUCTURE</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="{'Main navigation' if lang=='en' else 'Navegação principal'}">{nav}<a class="language-switch" href="{url(d['other'],key)}" lang="{D[d['other']]['lang']}" hreflang="{D[d['other']]['lang']}">{d['switch']}</a></nav></header><main id="main">{content(lang,key)}</main><footer class="site-footer"><div class="wrap footer-top"><a class="brand" href="{url(lang)}"><img src="/assets/feverdream-logo.webp" width="42" height="42" alt=""><span>FEVERDREAM</span></a><p>{d['footer']}</p><a href="mailto:vendas@feverdream.dev">vendas@feverdream.dev ↗</a></div><div class="wrap footer-bottom"><span>© 2026 FeverDream</span><div><a href="{url(lang,'projects')}">{d['nav'][1]}</a><a href="{url(lang,'opensource')}">{d['nav'][2]}</a><a href="https://www.linkedin.com/company/feverdreamdev">LinkedIn ↗</a><a href="https://www.instagram.com/feverdream.dev/">Instagram ↗</a></div><span>São Paulo / Brasil</span></div></footer></body></html>'''
def redirect(path,target):write(path,f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeverDream</title><link rel="canonical" href="{BASE+target}"><meta http-equiv="refresh" content="0;url={target}"></head><body><a href="{target}">Continue to FeverDream / Continuar</a></body></html>')
for lang in D:
 for key in KEYS:write(lang+'/'+(key+'/' if key else '')+'index.html',page(lang,key))
 for key in ['ai','dev','cloud','security','projects','opensource','about','contact']:
  redirect(f'{lang}/{key}.html',url(lang,'' if key=='index' else key))
redirect('index.html','/en/')
for key in ['ai','dev','cloud','security','projects','opensource','about','contact']:redirect(key+'.html',url('en',key))
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'+''.join('<url><loc>'+BASE+url(lang,key)+'</loc>'+''.join(f'<xhtml:link rel="alternate" hreflang="{D[l]["lang"]}" href="{BASE+url(l,key)}"/>' for l in D)+f'<xhtml:link rel="alternate" hreflang="x-default" href="{BASE+url("en",key)}"/></url>\n' for lang in D for key in KEYS)+'</urlset>\n')
write('robots.txt','User-agent: *\nAllow: /\n\nSitemap: https://feverdream.dev/sitemap.xml\n')
print('Built 22 canonical pages, legacy redirects, sitemap and robots.txt.')
